/// Represents a closed interval [start, end].
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Interval {
    pub start: f32,
    pub end: f32,
}

impl Interval {
    /// Specification‐only predicate: the interval must satisfy start <= end.
    #[verifier::spec]     // this method is only used in proofs
    #[verifier::pure]     // it has no side‐effects
    pub fn valid(self) -> bool {
        self.start <= self.end
    }
}

/// A Laguerre series characterized by its coefficients and two intervals:
///  - `domain`: the domain of the series
///  - `window`: the windowing interval
#[derive(Debug, Clone, PartialEq)]
pub struct Laguerre {
    pub coefficients: Vec<f32>,
    pub domain: Interval,
    pub window: Interval,
}

impl Laguerre {
    /// Spec predicate: a Laguerre is “valid” if both of its intervals are valid.
    #[verifier::spec]
    #[verifier::pure]
    pub fn valid(self) -> bool {
        self.domain.valid() && self.window.valid()
    }
}

